INSERT INTO posts (id, tenant_id, channel_id, author_id, slug, title, body, teaser, media_type, media_url, pinned, created_at, status, scheduled_at, kind, allow_comments, edited_at, body_html, anonymous, attachment_name) VALUES (1, 1, 1, 1, 'bienvenida-a-la-comunidad', '¡Bienvenidas y bienvenidos a la Comunidad Demo!', 'Este es nuestro espacio para compartir avances, hacer preguntas y celebrar logros.

Presentate en los comentarios: contanos quién sos, qué estás construyendo y qué esperás aprender aquí. Cada semana elegimos las mejores preguntas y las respondemos en vivo.', 'Presentate y conocé al resto de la comunidad.', 'none', '', 1, '2026-10-13T10:30:00.543Z', 'published', '', 'post', 1, '', '', 0, '');
INSERT INTO posts (id, tenant_id, channel_id, author_id, slug, title, body, teaser, media_type, media_url, pinned, created_at, status, scheduled_at, kind, allow_comments, edited_at, body_html, anonymous, attachment_name) VALUES (2, 1, 1, 2, 'asi-grabe-mi-primer-video', 'Así grabé mi primer video sin equipo caro', 'Grabé esta charla de ejemplo para mostrar que con buena luz y un guion corto se puede empezar hoy. Dejo el video que usamos de referencia en el taller y mis tres aprendizajes:

1. El guion manda: 5 líneas claras valen más que una hora improvisada.
2. Grabá en bloques cortos y editá después.
3. Publicá aunque no sea perfecto: la constancia vence al equipo.', 'Video y aprendizajes del taller de video corto.', 'video', 'https://www.youtube.com/embed/aqz-KE-bpKQ', 0, '2026-10-15T10:30:00.543Z', 'published', '', 'post', 1, '', '', 0, '');
INSERT INTO posts (id, tenant_id, channel_id, author_id, slug, title, body, teaser, media_type, media_url, pinned, created_at, status, scheduled_at, kind, allow_comments, edited_at, body_html, anonymous, attachment_name) VALUES (3, 1, 2, 1, 'calendario-de-octubre', 'Calendario: dos encuentros en vivo este mes', 'Este mes tenemos dos encuentros: una sesión de preguntas y respuestas y un taller práctico de planificación de contenido. Ambos quedan grabados y subidos a la biblioteca para miembros.

Revisá la sección de Eventos para reservar tu lugar.', 'Reservá tu lugar en los encuentros del mes.', 'none', '', 0, '2026-10-16T10:30:00.543Z', 'published', '', 'post', 1, '', '', 0, '');
INSERT INTO posts (id, tenant_id, channel_id, author_id, slug, title, body, teaser, media_type, media_url, pinned, created_at, status, scheduled_at, kind, allow_comments, edited_at, body_html, anonymous, attachment_name) VALUES (4, 1, 3, 4, 'como-organizo-mi-contenido', '¿Cómo organizan su contenido de la semana?', 'Estoy probando planificar el domingo pero me quedo sin ideas a mitad de semana. ¿Usan alguna plantilla o método simple que les funcione? Gracias por compartir.', 'Busco un método simple para planificar la semana.', 'none', '', 0, '2026-10-17T10:30:00.543Z', 'published', '', 'post', 1, '', '', 0, '');
INSERT INTO posts (id, tenant_id, channel_id, author_id, slug, title, body, teaser, media_type, media_url, pinned, created_at, status, scheduled_at, kind, allow_comments, edited_at, body_html, anonymous, attachment_name) VALUES (5, 1, 4, 3, 'plantilla-de-planificacion-2026', 'Plantilla completa de planificación de contenido 2026', 'Aquí está la plantilla completa que uso con mis clientes: calendario mensual, banco de ideas con puntuación, guiones por formato y una hoja de revisión semanal.

Incluye el paso a paso para adaptarla a una sola persona o a un equipo, y los errores más comunes al planificar (con su corrección). Descargala desde la biblioteca, sección Recursos Premium.', 'La plantilla completa, con el paso a paso, está disponible solo para miembros con acceso a este canal.', 'none', '', 0, '2026-10-18T10:30:00.543Z', 'published', '', 'post', 1, '', '', 0, '');
INSERT INTO posts (id, tenant_id, channel_id, author_id, slug, title, body, teaser, media_type, media_url, pinned, created_at, status, scheduled_at, kind, allow_comments, edited_at, body_html, anonymous, attachment_name) VALUES (6, 1, 4, 1, 'sesion-exclusiva-revision', 'Sesión exclusiva: revisión de proyectos de miembros', 'Cada mes reviso en detalle tres proyectos de miembros de este canal. Dejá el tuyo en los comentarios de esta publicación para entrar en la selección de este mes.', 'Traé tu proyecto a la revisión mensual.', 'none', '', 0, '2026-10-18T12:30:00.543Z', 'published', '', 'post', 1, '', '', 0, '');
INSERT INTO posts (id, tenant_id, channel_id, author_id, slug, title, body, teaser, media_type, media_url, pinned, created_at, status, scheduled_at, kind, allow_comments, edited_at, body_html, anonymous, attachment_name) VALUES (7, 1, 5, 1, 'notas-de-la-sala-privada', 'Notas de la sala privada', 'Este canal es solo para miembros registrados. Aquí coordinamos las pruebas internas y los adelantos antes de publicarlos en el resto de la comunidad.', 'Coordinación interna de miembros.', 'none', '', 0, '2026-10-19T09:30:00.543Z', 'published', '', 'post', 1, '', '', 0, '');
