INSERT INTO courses (id, tenant_id, slug, title, description, level, price_cents, created_at, status, image_url, short_description, description_html, banner_url, visibility, enroll_limit, drip_mode, certificate_enabled, certificate_blueprint_id) VALUES (1, 1, 'crea-tu-comunidad', 'Creá tu primera comunidad en línea', 'De cero a una comunidad activa: estructura, reglas, canales y los primeros 90 días de contenido.', 'Principiante', 0, '2026-10-19T05:15:09.543Z', 'published', '', '', '', '', 'public', 0, 'none', 1, NULL);
