INSERT INTO lessons (id, tenant_id, chapter_id, title, duration_min, is_free, sort, content, video_url, kind, content_html, file_url, file_name, embed_url, allow_download, prerequisite, resource_url, resource_name, unlock_offset_days, unlock_at, status) VALUES (1, 1, 1, 'Qué hace que una comunidad funcione', 9, 1, 1, 'Una comunidad no funciona por la plataforma: funciona porque la gente vuelve. Y la gente vuelve por tres cosas: sentirse vista, aprender algo útil y conocer a otras personas como ella.

En esta lección revisamos ejemplos reales de comunidades que crecieron sin publicidad y detectamos el patrón común: rituales semanales simples, respuestas rápidas a cada nuevo miembro y un espacio claro para compartir logros.

Ejercicio: escribí en una frase qué obtiene alguien que participa activamente durante un mes en tu comunidad. Esa frase va a guiar todo lo demás.', '', 'text', '', '', '', '', 0, 0, '', '', NULL, '', 'published');
INSERT INTO lessons (id, tenant_id, chapter_id, title, duration_min, is_free, sort, content, video_url, kind, content_html, file_url, file_name, embed_url, allow_download, prerequisite, resource_url, resource_name, unlock_offset_days, unlock_at, status) VALUES (2, 1, 1, 'Definí tu promesa y tu audiencia', 12, 0, 2, 'La promesa es el resultado concreto que tu comunidad ayuda a lograr: no "un espacio para emprendedores", sino "salir con tu primer cliente en 90 días". Cuanto más específica, mejor filtra y mejor retiene.

Tu audiencia inicial debería ser un grupo pequeño y reconocible: las primeras 50 personas definen la cultura. Hablales en su idioma, con sus problemas reales, y evitá mezclar públicos que no se hablan entre sí.

Al terminar, completá esta plantilla: "Ayudo a [audiencia] a lograr [resultado] mediante [método o dinámica de la comunidad]".', '', 'text', '', '', '', '', 0, 0, '', '', NULL, '', 'published');
INSERT INTO lessons (id, tenant_id, chapter_id, title, duration_min, is_free, sort, content, video_url, kind, content_html, file_url, file_name, embed_url, allow_download, prerequisite, resource_url, resource_name, unlock_offset_days, unlock_at, status) VALUES (3, 1, 2, 'Canales y reglas claras desde el día uno', 14, 0, 1, 'Menos canales, mejor comunidad: empezá con tres a cinco espacios con propósito evidente (presentaciones, dudas, logros y un canal social). Cada canal nuevo se crea cuando el contenido ya existe y no encuentra lugar, nunca antes.

Las reglas deben ser cortas, positivas y visibles: qué se celebra, qué se mueve a otro canal y qué se elimina. Publicalas dentro de la comunidad y enlazalas en el mensaje de bienvenida.

Checklist de lanzamiento: canal de presentaciones con una pregunta rompehielos, reglas fijadas, primer evento agendado y tres publicaciones semilla tuyas.', '', 'text', '', '', '', '', 0, 0, '', '', NULL, '', 'published');
INSERT INTO lessons (id, tenant_id, chapter_id, title, duration_min, is_free, sort, content, video_url, kind, content_html, file_url, file_name, embed_url, allow_download, prerequisite, resource_url, resource_name, unlock_offset_days, unlock_at, status) VALUES (4, 1, 2, 'Tu plan de contenido de 90 días', 18, 0, 2, 'Noventa días es el horizonte mínimo para que una comunidad despegue: tiempo suficiente para crear hábito sin quemarte. El plan combina cuatro tipos de contenido en rotación: enseñar (tutoriales cortos), conversar (preguntas abiertas), celebrar (logros de miembros) y reunir (eventos en vivo).

Armá una grilla semanal repetible — por ejemplo: lunes de pregunta, miércoles de recurso, viernes de logros — y prepará el contenido en bloques de dos horas.

Regla de oro: tu contenido siembra, pero la meta es que en el día 90 la mitad de las publicaciones nazcan de los miembros. Medilo cada mes.', '', 'text', '', '', '', '', 0, 0, '', '', NULL, '', 'published');
INSERT INTO lessons (id, tenant_id, chapter_id, title, duration_min, is_free, sort, content, video_url, kind, content_html, file_url, file_name, embed_url, allow_download, prerequisite, resource_url, resource_name, unlock_offset_days, unlock_at, status) VALUES (5, 1, 3, 'El gancho de los primeros 3 segundos', 8, 1, 1, 'Nadie decide ver tu video por el tema: decide por la primera frase. Un buen gancho promete un resultado, abre una pregunta o contradice una creencia común: "Estás editando tus videos al revés y por eso nadie los termina".

Escribí el gancho antes que el resto del guion y grabalo en dos versiones. Si el gancho no te genera curiosidad a vos, no va a generársela a nadie.

Práctica: tomá tu último video y reescribí solo los primeros 3 segundos con estas tres fórmulas. Grabá la versión nueva y compará la retención.', '', 'text', '', '', '', '', 0, 0, '', '', NULL, '', 'published');
INSERT INTO lessons (id, tenant_id, chapter_id, title, duration_min, is_free, sort, content, video_url, kind, content_html, file_url, file_name, embed_url, allow_download, prerequisite, resource_url, resource_name, unlock_offset_days, unlock_at, status) VALUES (6, 1, 3, 'Luz y sonido con lo que ya tenés', 11, 0, 2, 'La gente perdona una imagen regular; no perdona un audio malo. Acercate al micrófono del teléfono o de los auriculares, grabá en el cuarto con más muebles y cortinas de tu casa, y apagá ventiladores y notificaciones.

Para la luz: enfrentá una ventana o una lámpara suave, nunca la tengas detrás. Si grabás de noche, una lámpara con pantalla frente a vos, levemente elevada, alcanza.

Antes de grabar en serio, hacé una toma de prueba de 15 segundos y escuchala con auriculares. Ese hábito simple evita el 90% de los videos que hay que repetir.', '', 'text', '', '', '', '', 0, 0, '', '', NULL, '', 'published');
INSERT INTO lessons (id, tenant_id, chapter_id, title, duration_min, is_free, sort, content, video_url, kind, content_html, file_url, file_name, embed_url, allow_download, prerequisite, resource_url, resource_name, unlock_offset_days, unlock_at, status) VALUES (7, 1, 4, 'Cortes que mantienen la atención', 15, 0, 1, 'Editar video corto es, sobre todo, sacar: silencios mayores a medio segundo, muletillas y cualquier frase que no agregue información o emoción. Cada corte debe ganarse su lugar.

Trabajá en dos pasadas: primero la estructura (que la historia se entienda sin mirar la pantalla) y después el ritmo (acercamientos, textos en pantalla y cambios de plano cada pocos segundos).

Cerrá siempre con una sola llamada a la acción: comentar una palabra, guardar el video o seguirte para la parte dos. Una sola.', '', 'text', '', '', '', '', 0, 0, '', '', NULL, '', 'published');
INSERT INTO lessons (id, tenant_id, chapter_id, title, duration_min, is_free, sort, content, video_url, kind, content_html, file_url, file_name, embed_url, allow_download, prerequisite, resource_url, resource_name, unlock_offset_days, unlock_at, status) VALUES (8, 1, 4, 'Títulos y portadas que invitan a ver', 10, 0, 2, 'El título no resume el video: vende el clic. Prometé un resultado específico o una tensión concreta, en menos de ocho palabras: "3 errores que matan tu primer video" funciona mejor que "Consejos de grabación".

La portada se lee en un segundo: un rostro con expresión clara, tres palabras grandes como máximo y contraste fuerte. Evitá repetir el título entero en la portada: se complementan, no se duplican.

Publicá, medí el porcentaje de clics a las 48 horas y ajustá un solo elemento por vez. Así aprendés qué mueve la aguja en TU audiencia.', '', 'text', '', '', '', '', 0, 0, '', '', NULL, '', 'published');
